package com.simhastha.service;
import com.simhastha.model.Ghat; import java.time.Duration; import java.util.Optional; import java.util.concurrent.ConcurrentHashMap;
/** Provider slot with 15-minute coordinate cache. The default provider is deliberately unavailable. */
public final class WeatherService { public interface Provider { Optional<Ghat.Weather> fetch(double lat,double lon); } private final Provider provider; private final ConcurrentHashMap<String,Entry> cache=new ConcurrentHashMap<>(); private final Duration ttl=Duration.ofMinutes(Long.getLong("ghats.weather.cache.minutes",15)); public WeatherService(){this((a,b)->Optional.empty());} public WeatherService(Provider provider){this.provider=provider;} public Ghat.Weather weather(Double lat,Double lon){if(lat==null||lon==null)return Ghat.Weather.unavailable();String key=Math.round(lat*1000)+":"+Math.round(lon*1000);Entry old=cache.get(key);if(old!=null&&System.currentTimeMillis()-old.at<ttl.toMillis())return old.weather;Ghat.Weather weather=provider.fetch(lat,lon).orElse(Ghat.Weather.unavailable());cache.put(key,new Entry(weather,System.currentTimeMillis()));return weather;} private record Entry(Ghat.Weather weather,long at){} }
